<!doctype html><html lang="vi"><head>
    <base href="view/"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cửa hàng trực tuyến | Starbucks</title><style>
:root{font-family:system-ui,Arial,sans-serif;color:#1e3932;background:#f7faf7}*{box-sizing:border-box}body{margin:0}header{background:#006241;color:white;padding:22px 6%;display:flex;gap:22px;align-items:center;flex-wrap:wrap}a{color:inherit}header a{text-decoration:none;color:white}main{max-width:1150px;margin:35px auto;padding:0 20px}.layout{display:grid;grid-template-columns:1fr 320px;gap:30px}.products{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:20px}.product{background:white;border-radius:17px;overflow:hidden;box-shadow:0 5px 18px #163d2920}.product img{width:100%;height:170px;object-fit:cover}.product .info{padding:16px}.product h3{margin:0 0 8px}.price{font-weight:700;color:#006241}.panel{background:white;border-radius:16px;padding:20px;box-shadow:0 5px 18px #163d2920;height:max-content}button{border:0;background:#006241;color:white;border-radius:10px;padding:11px 16px;cursor:pointer}button:hover{background:#004a32}input,select{width:100%;padding:10px;border:1px solid #ccd6ce;border-radius:8px;margin:7px 0 12px}#cartList{padding-left:20px}.muted{color:#52665b;font-size:13px}@media(max-width:750px){.layout{grid-template-columns:1fr}}
</style></head><body><header><strong style="font-size:24px">☕ Starbucks</strong><a href="../index.php?page=index">Trang chủ</a><a href="../index.php?page=sanpham">Sản phẩm (giao diện gốc)</a><a href="../index.php?page=dangnhap">Đăng nhập</a><a href="../admin/index.php">Quản trị</a></header><main><h1>Cửa hàng • Sản phẩm từ MySQL</h1><p>Chọn món, thêm vào giỏ và đặt hàng. Giá và tổng tiền được máy chủ xác nhận.</p><label>Danh mục <select id="category"><option value="0">Tất cả</option></select></label><div class="layout"><section class="products" id="products">Đang tải...</section><aside class="panel"><h2>🛒 Giỏ hàng</h2><ol id="cartList"></ol><p><strong>Tạm tính: <span id="total">0đ</span></strong></p><form id="orderForm"><label>Người nhận<input name="name" required minlength="2"></label><label>Điện thoại<input name="phone" required></label><label>Địa chỉ giao hàng<input name="address" required minlength="5"></label><label>Thanh toán<select name="payment_method"><option value="cod">Khi nhận hàng (COD)</option><option value="bank_transfer">Chuyển khoản (chờ xác nhận)</option></select></label><button type="submit">Đặt hàng</button></form><p class="muted">Đơn chuyển khoản chỉ ở trạng thái chờ xác nhận; đây không phải cổng thanh toán tự động.</p></aside></div></main><script src="backend.js"></script><script>
const api=window.StarbucksAPI;let products=[],cart=[];let money=n=>Number(n).toLocaleString('vi-VN')+'đ';let esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
async function load(){try{let cs=await api('categories');document.querySelector('#category').innerHTML='<option value="0">Tất cả</option>'+cs.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');await loadProducts();}catch(e){document.querySelector('#products').textContent=e.message;}}
async function loadProducts(){const cat=document.querySelector('#category').value;let res=await api('products'+(cat!=='0'?'&category='+cat:''));products=res.products;document.querySelector('#products').innerHTML=products.map(p=>`<article class="product"><img alt="${esc(p.name)}" src="${esc(p.image_url||'')}" loading="lazy"><div class="info"><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p><p class="price">${money(p.price)}</p><p class="muted">Còn ${p.stock} sản phẩm</p><button onclick="add(${p.id})" ${Number(p.stock)===0?'disabled':''}>Thêm vào giỏ</button></div></article>`).join('')||'Không có sản phẩm';}
function add(id){const p=products.find(x=>Number(x.id)===id);if(!p)return;let item=cart.find(x=>x.id===id);if(item){if(item.quantity>=p.stock)return alert('Không đủ hàng');item.quantity++}else cart.push({id,quantity:1,name:p.name,price:Number(p.price)});render()}
function change(id,d){const x=cart.find(x=>x.id===id);if(!x)return;x.quantity+=d;if(x.quantity<=0)cart=cart.filter(c=>c!==x);render()}
function render(){document.querySelector('#cartList').innerHTML=cart.map(x=>`<li>${esc(x.name)} × ${x.quantity} <button type="button" onclick="change(${x.id},-1)">−</button> <button type="button" onclick="change(${x.id},1)">+</button></li>`).join('')||'<li>Chưa có món</li>';document.querySelector('#total').textContent=money(cart.reduce((t,x)=>t+x.price*x.quantity,0))}
document.querySelector('#category').onchange=loadProducts;document.querySelector('#orderForm').onsubmit=async e=>{e.preventDefault();if(!cart.length)return alert('Giỏ hàng trống');const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.items=cart.map(({id,quantity})=>({id,quantity}));const response=await api('order',data);alert('Đặt hàng thành công! Mã đơn: '+response.code+' - Tổng: '+money(response.total)+'\nĐơn hàng đang chờ xác nhận.');cart=[];render();e.target.reset();await loadProducts();}catch(err){alert(err.message)}finally{b.disabled=false}};load();
</script></body></html>